<template>
  <view class="test-container">
    <!-- 顶部导航区域 -->
   <NavBar
      :title="navTitle"
      @back="onClickBack" />

    <!-- 主内容区域 -->
    <view class="content-container">
      <SwiperLimitLoad
        ref="swiperRef"
        :current="initCurrentIndex"
        :duration="swiperDuration"
        :total="resultObj.total"
        @transition="swiperTransitionEvent"
        @change="swiperChangeEvent">
        <template v-slot:content="{ listData }">
          <TopicInfo
            :topicInfo="listData"
            :answerMode="1"
            :isAnalysis="false"
            @selected="postSelectCallBack" />
        </template>
      </SwiperLimitLoad>
    </view>

    <view class="button-container">
      <!-- 如果当前到达第一题则禁用上一题按钮 -->
      <button
        :disabled="initCurrentIndex === 0"
        @click="onClickPrevious">
        上一题
      </button>

      <!-- <button @click="onClickAnswerSheet">答题卡</button> -->

      <!-- 如果当前到达最后一题则禁用下一题按钮 -->
      <button
		v-if="initCurrentIndex !== resultObj.total - 1"
        @click="onClickNext">
        下一题
      </button>
	  <button
		v-else
	    class="submit-btn"
	    type="primary"
	    @tap="onClickSubmit">
	    提交答案
	  </button>
    </view>

    <!-- 答题卡弹出层区域 -->
    <!-- <Popup
      :display="displayPopup"
      @clickMask="onClickMask">
      <view class="answer-sheet-container">
        <text class="answer-sheet-title">答题卡</text>

